/**
 * Generate the mobile rrweb-player bundle module.
 *
 * The web ReplayPlayerModal inlines `rrweb-player/dist/rrweb-player.umd.min.cjs`
 * + `style.css` as raw text (Vite `?raw`) into a sandboxed iframe. Metro has no
 * `?raw` equivalent, so the mobile WebView player reads the same two files from
 * a committed module instead. This script regenerates that module from the
 * pinned rrweb-player dist so a dependency bump is a one-command refresh.
 *
 * Source of truth is `client/node_modules/rrweb-player/dist` — the exact files
 * the web player inlines and `client/src/utils/replayPlayerBundle.test.ts`
 * guards — so mobile and web ship byte-identical player code. Run:
 *   node scripts/generate-mobile-rrweb-bundle.mjs
 * then commit the regenerated `mobile/src/utils/rrwebPlayerBundle.generated.ts`.
 */
import { readFileSync, writeFileSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const distDir = path.join(root, 'client', 'node_modules', 'rrweb-player', 'dist');
const jsPath = path.join(distDir, 'rrweb-player.umd.min.cjs');
const cssPath = path.join(distDir, 'style.css');
const outPath = path.join(root, 'mobile', 'src', 'utils', 'rrwebPlayerBundle.generated.ts');

let js;
let css;
try {
  js = readFileSync(jsPath, 'utf8');
  css = readFileSync(cssPath, 'utf8');
} catch (err) {
  console.error(
    `Could not read rrweb-player dist from ${distDir}.\n` +
      'Install the client deps first: (cd client && npm install), then re-run.',
  );
  console.error(String(err?.message || err));
  process.exit(1);
}

// JSON.stringify yields a valid, fully-escaped JS string literal for arbitrary
// bytes (backticks, backslashes, `${`, newlines) — safer than hand-escaping a
// 200KB+ minified blob.
const banner =
  '// AUTO-GENERATED by scripts/generate-mobile-rrweb-bundle.mjs — DO NOT EDIT BY HAND.\n' +
  '// Regenerate after bumping rrweb-player: node scripts/generate-mobile-rrweb-bundle.mjs\n' +
  '// Byte-identical to the rrweb-player dist the web ReplayPlayerModal inlines\n' +
  '// (client/node_modules/rrweb-player/dist/{rrweb-player.umd.min.cjs,style.css}).\n';

const body =
  `export const RRWEB_PLAYER_JS = ${JSON.stringify(js)};\n` +
  `export const RRWEB_PLAYER_CSS = ${JSON.stringify(css)};\n`;

writeFileSync(outPath, banner + body);
console.log(
  `Wrote ${outPath} (js ${js.length} bytes, css ${css.length} bytes → ${
    banner.length + body.length
  } bytes).`,
);
